"""Independent single-round Linear golden, including cancellation near rounding ties."""

from pathlib import Path
import subprocess

import torch

m, k, n = 3, 16, 32
torch.manual_seed(1907)
a = torch.randn(m, k)
b = torch.randn(k, n)
bias = torch.randn(n)
lines = [
    "// Generated by generate_single_round_fixtures.py; PyTorch F.linear, one output cast."
]
for name, dtype in [("F16", torch.float16), ("BF16", torch.bfloat16)]:
    x = a.to(dtype)
    w = b.T.contiguous().to(dtype)
    z = bias.to(dtype)
    result = torch.nn.functional.linear(x, w, z)
    separate = (x @ w.T) + z
    assert not torch.equal(result, separate)
    for key, value in [("A", x), ("B", w.T.contiguous()), ("BIAS", z), ("OUTPUT", result)]:
        bits = value.view(torch.uint16).flatten().tolist()
        lines.append(f"pub const {name}_{key}: &[u16] = &{bits};")
output = Path(__file__).with_name("torch_single_round_fixtures.rs")
output.write_text("\n".join(lines) + "\n")
subprocess.run(["rustfmt", "--edition", "2021", str(output)], check=True)
